package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record Withdrawal(LedgerEntry entry) { public Withdrawal { if(entry.type()!=LedgerEntryType.WITHDRAWAL) throw new IllegalArgumentException("Wrong ledger type"); } public static Withdrawal of(UserId user,Money amount,String reference){ return new Withdrawal(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.WITHDRAWAL,amount,reference,java.time.Instant.now())); } }